@Test(groups = "billing")
public void totalEqualsSumOfLineItems() {
    InvoiceResponse invoice = given()
            .spec(billingSpec)
        .when()
            .get("/api/v1/invoices/{id}", INVOICE_ID)
        .then()
            .statusCode(200)
            .extract().as(InvoiceResponse.class);

    BigDecimal expected = new BigDecimal("100.00");
    assertEquals(invoice.getTotal(), expected, "Invoice total mismatch");
}
